int main() {
    initgraph(WINDOW_W, WINDOW_H);
    BeginBatchDraw();
    
    // Scale factor for the grid (800 / 320 = 2.5 pixels per block)
    float scale = 2.5f;
    int drawX = (WINDOW_W - (GRID_W * scale)) / 2;
    int drawY = (WINDOW_H - (GRID_H * scale)) / 2;

    for (int y = 0; y < GRID_H; y++) {
        for (int x = 0; x < GRID_W; x++) {
            unsigned long c = STAR_PIXELS[y * GRID_W + x];
            int r = (c >> 16) & 0xFF;
            int g = (c >> 8) & 0xFF;
            int b = c & 0xFF;
            
            setfillcolor(RGB(r, g, b));
            
            // Draw each pixel block
            int px = drawX + (x * scale);
            int py = drawY + (y * scale);
            solidrectangle(px, py, px + scale, py + scale);
        }
    }

    FlushBatchDraw();
    
    // Wait for user to press ESC
    while (true) {
        if (_kbhit() && _getch() == 27) break;
        Sleep(10);
    }

    closegraph();
    return 0;
}
